package net.civeira.phylax.features.access.userroleassignament.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.userroleassignament.domain.UserRoleAssignament;
import net.civeira.phylax.features.access.userroleassignament.domain.event.UserRoleAssignamentEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserRoleAssignamentEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserRoleAssignamentEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserRoleAssignament entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
